package org.opengridseg.io;
import ij.IJ; import ij.ImagePlus; import ij.process.FloatProcessor; import java.nio.file.Path; import java.util.regex.*; import org.opengridseg.image.FloatPlane;
public final class TiffPlaneReader { private static final Pattern SIGNIFICANT=Pattern.compile("(?:Camera )?Bit Depth[^0-9]*(\\d+)(?:-bit)?",Pattern.CASE_INSENSITIVE); private TiffPlaneReader(){} public static SourcePlane read(Path path){ImagePlus image=IJ.openImage(path.toString());if(image==null)throw new IllegalArgumentException("Cannot open TIFF: "+path);if(image.getStackSize()!=1)throw new IllegalArgumentException("Expected one plane per TIFF: "+path);int bits=image.getBitDepth();String type=bits==8?"uint8":bits==16?"uint16":bits==32?"float32":"unknown";FloatProcessor fp=image.getProcessor().convertToFloatProcessor();float[] pixels=((float[])fp.getPixels()).clone();FloatPlane plane=new FloatPlane(fp.getWidth(),fp.getHeight(),pixels);Integer significant=null;Object info=image.getProperty("Info");if(info!=null){Matcher m=SIGNIFICANT.matcher(info.toString());if(m.find())significant=Integer.valueOf(m.group(1));}SourcePlane result=new SourcePlane(path,plane,type,bits,significant,plane.min(),plane.max());image.close();return result;} }
